 72	    @Override
 73	    @Transactional
 74	    public Claim create(CreateClaimCommand command, Actor actor, String key, String correlationId) {
 75	        requireHuman(actor);
 76	        requireRole(actor, "member");
 77	        String scope = "claims:create";
 78	        String fingerprint = fingerprint(Map.of("policyLimit", command.policyLimit(), "currency", command.currency(),
 79	                "facts", command.facts().values()));
 80	        idempotency.lock(actor.id(), scope, requireKey(key));
 81	        Optional<Claim> replay = replay(actor.id(), scope, key, fingerprint, Claim.class);
 82	        if (replay.isPresent()) return replay.get();
 83	        Instant now = now();
 84	        validateRequestedAmount(command.facts().values().get("requestedAmount"));
 85	        if (!command.facts().values().keySet().stream().allMatch("requestedAmount"::equals))
 86	            throw forbidden("Only requestedAmount may be supplied when a claim is created");
 87	        Object requestedAmount = command.facts().values().get("requestedAmount");
 88	        if (!(requestedAmount instanceof BigDecimal amount) || amount.compareTo(command.policyLimit()) > 0)
 89	            throw invalid("requestedAmount must be present and no greater than the policy limit");
 90	        Claim claim = new Claim(UUID.randomUUID(), actor.id(), definition.initialState(), command.policyLimit(),
 91	                command.currency(), 0, command.facts(), now, now);
 92	        claims.insert(new ClaimAggregate(claim, ClaimWorkflowData.empty()));
 93	        writeSystemAudit("claim.create", "claim", claim.id().toString(), actor, correlationId, "success", null);
 94	        storeReceipt(actor.id(), scope, key, fingerprint, claim);
 95	        return claim;
 96	    }
