123	    public Claim updateFacts(UUID claimId, UpdateFactsCommand command, Actor actor, String key, String correlationId) {
124	        requireHuman(actor);
125	        String scope = "claims:" + claimId + ":facts";
126	        String fingerprint = fingerprint(Map.of("expectedVersion", command.expectedVersion(), "facts", command.facts().values()));
127	        lockAndCheckKey(actor, scope, key);
128	        Optional<Claim> replay = replay(actor.id(), scope, key, fingerprint, Claim.class);
129	        if (replay.isPresent()) return replay.get();
130	        ClaimAggregate current = lockedClaim(claimId, actor);
131	        checkVersion(current.claim(), command.expectedVersion());
132	        ClaimFacts merged = mergeFacts(current.claim(), command.facts(), actor);
133	        ClaimWorkflowData data = current.workflow();
134	        if (actor.hasRole("member") && current.claim().state().equals("PENDING_INFO")) {
135	            data = new ClaimWorkflowData(data.informationRequests(), data.lastInformationRequestedAt(), now(),
136	                    data.assessmentStartedAt(), data.rejectedAt(), data.memberAcknowledgedRejectionAt());
137	        }
138	        Claim updated = replace(current.claim(), current.claim().state(), merged, current.claim().version() + 1, now());
139	        if (!claims.compareAndSet(new ClaimAggregate(updated, data), command.expectedVersion())) throw versionConflict();
140	        writeSystemAudit("claim.facts.update", "claim", claimId.toString(), actor, correlationId, "success", null);
141	        storeReceipt(actor.id(), scope, key, fingerprint, updated);
142	        return updated;
143	    }
