148	        requireHuman(actor);
149	        requireRole(actor, "member");
150	        String scope = "claims:" + claimId + ":rejection-acknowledgement";
151	        String fingerprint = fingerprint(Map.of("expectedVersion", expectedVersion, "action", "acknowledge-rejection"));
152	        lockAndCheckKey(actor, scope, key);
153	        Optional<Claim> replay = replay(actor.id(), scope, key, fingerprint, Claim.class);
154	        if (replay.isPresent()) return replay.get();
155	        ClaimAggregate current = lockedClaim(claimId, actor);
156	        checkVersion(current.claim(), expectedVersion);
157	        if (!current.claim().state().equals("REJECTED"))
158	            throw new BusinessException("INVALID_STATE", "Only a rejected claim can be acknowledged", 409);
159	        Instant acknowledgedAt = now();
160	        ClaimWorkflowData old = current.workflow();
161	        ClaimWorkflowData data = new ClaimWorkflowData(old.informationRequests(), old.lastInformationRequestedAt(),
162	                old.lastInformationReceivedAt(), old.assessmentStartedAt(), old.rejectedAt(), acknowledgedAt);
163	        Claim updated = replace(current.claim(), current.claim().state(), current.claim().facts(),
164	                current.claim().version() + 1, acknowledgedAt);
165	        if (!claims.compareAndSet(new ClaimAggregate(updated, data), expectedVersion)) throw versionConflict();
166	        writeSystemAudit("claim.rejection.acknowledge", "claim", claimId.toString(), actor, correlationId, "SUCCESS", null);
167	        storeReceipt(actor.id(), scope, key, fingerprint, updated);
