195	    private TransitionResult doTransition(UUID claimId, TransitionCommand command, Actor actor,
196	            String key, String correlationId, boolean systemCall) {
197	        String scope = "claims:" + claimId + ":transition";
198	        String fingerprint = fingerprint(Map.of("targetState", command.targetState(),
199	                "expectedVersion", command.expectedVersion(), "reason", command.reason(),
200	                "facts", command.suppliedFacts().values(), "system", systemCall));
201	        lockAndCheckKey(actor, scope, key);
202	        Optional<TransitionResult> replay = replay(actor.id(), scope, key, fingerprint, TransitionResult.class);
203	        if (replay.isPresent()) {
204	            TransitionResult result = replay.get();
205	            return new TransitionResult(result.claim(), result.audit(), true);
206	        }
207	        ClaimAggregate current = lockedClaim(claimId, actor);
208	        checkVersion(current.claim(), command.expectedVersion());
209	        ClaimFacts merged = command.suppliedFacts().values().isEmpty()
210	                ? current.claim().facts() : mergeFacts(current.claim(), command.suppliedFacts(), actor);
211	        Claim candidate = replace(current.claim(), current.claim().state(), merged,
212	                current.claim().version(), current.claim().updatedAt());
213	        WorkflowEvidence evidence = evidence(current.workflow(), claimId);
214	        WorkflowDecision decision = workflow.evaluate(new WorkflowEvaluationContext(candidate, actor, command,
215	                evidence, now(), appealPeriod));
216	        if (!decision.allowed()) throw new BusinessException(decision.failureCode(), decision.failureMessage(),
217	                decision.failureCode().equals("ROLE_FORBIDDEN") ? 403 : 409);
218	
219	        Instant occurred = now();
220	        ClaimWorkflowData nextData = updateWorkflowData(current.workflow(), decision, occurred);
221	        ClaimFacts nextFacts = clearStaleAssessmentFacts(merged, decision);
222	        Claim updated = replace(candidate, decision.to(), nextFacts, current.claim().version() + 1, occurred);
223	        if (!claims.compareAndSet(new ClaimAggregate(updated, nextData), command.expectedVersion())) throw versionConflict();
224	
225	        String role = matchingRole(actor, decision.transitionId());
226	        AuditRecord audit = new AuditRecord(UUID.randomUUID(), claimId, updated.version(), occurred,
227	                decision.from(), decision.to(), actor.id(), role, command.reason(), safeCorrelation(correlationId), definition.version());
228	        claimAudit.append(audit);
229	        persistEffects(decision.effects(), claimId, candidate);
230	        writeSystemAudit(systemCall ? "claim.system-transition" : "claim.transition", "claim", claimId.toString(),
231	                actor, correlationId, "success", null);
232	        TransitionResult result = new TransitionResult(updated, audit, false);
233	        storeReceipt(actor.id(), scope, key, fingerprint, result);
234	        return result;
235	    }
