237	    private void persistEffects(List<EffectIntent> intents, UUID claimId, Claim claim) {
238	        Instant available = now().plus(dispatchDelay);
239	        for (EffectIntent intent : intents) {
240	            if (intent.id().equals("create_payment_request")) {
241	                Object rawAmount = claim.facts().values().get("requestedAmount");
242	                if (!(rawAmount instanceof BigDecimal amount)) throw invalid("Requested amount must be an exact decimal");
243	                payments.create(claimId, UUID.randomUUID(), claim.currency(), amount);
244	            }
245	            outbox.enqueue(new OutboxRepository.Message(UUID.randomUUID(), claimId, intent.id(),
246	                    writeJson(intent.payload()), 0, available));
247	        }
248	    }
