250	    private ClaimWorkflowData updateWorkflowData(ClaimWorkflowData old, WorkflowDecision decision, Instant now) {
251	        int requests = old.informationRequests();
252	        Instant requested = old.lastInformationRequestedAt();
253	        Instant assessment = old.assessmentStartedAt();
254	        Instant rejected = old.rejectedAt();
255	        Instant acknowledged = old.memberAcknowledgedRejectionAt();
256	        for (EffectIntent effect : decision.effects()) {
257	            switch (effect.id()) {
258	                case "record_assessment_start" -> assessment = now;
259	                case "notify_information_request" -> { requests++; requested = now; }
260	                case "reset_assessment_timer" -> assessment = null;
261	                case "notify_member_rejection" -> { rejected = now; acknowledged = null; }
262	                default -> { }
263	            }
264	        }
265	        return new ClaimWorkflowData(requests, requested, old.lastInformationReceivedAt(), assessment, rejected, acknowledged);
266	    }
