 15	@Component
 16	public class OutboxDispatcher {
 17	    private static final Logger log = LoggerFactory.getLogger(OutboxDispatcher.class);
 18	    private final OutboxRepository outbox;
 19	    private final EffectDelivery delivery;
 20	    private final Clock clock;
 21	    private final Duration retryDelay;
 22	    private final int batchSize;
 23	    private final MeterRegistry metrics;
 24	
 25	    public OutboxDispatcher(OutboxRepository outbox, EffectDelivery delivery, Clock clock, MeterRegistry metrics,
 26	            @Value("${claims.outbox.retry-delay-ms:5000}") long retryDelayMs,
 27	            @Value("${claims.outbox.batch-size:32}") int batchSize) {
 28	        if (retryDelayMs < 1 || batchSize < 1) throw new IllegalArgumentException("Outbox retry delay and batch size must be positive");
 29	        this.outbox = outbox; this.delivery = delivery; this.clock = clock;
 30	        this.retryDelay = Duration.ofMillis(retryDelayMs); this.batchSize = batchSize; this.metrics = metrics;
 31	    }
 32	
 33	    @Scheduled(fixedDelayString = "${claims.outbox.poll-interval-ms:1000}")
 34	    @Transactional
 35	    public void dispatchDue() {
 36	        List<OutboxRepository.Message> batch = outbox.claimDue(clock.instant(), batchSize);
 37	        for (OutboxRepository.Message message : batch) {
 38	            try {
 39	                delivery.deliver(message);
 40	                if (outbox.markDelivered(message.id(), clock.instant())) {
 41	                    metrics.counter("claims.outbox.delivered", "effect", message.effect()).increment();
 42	                }
 43	            } catch (RuntimeException failure) {
 44	                outbox.markFailed(message.id(), failure.getClass().getSimpleName(), clock.instant().plus(retryDelay));
 45	                metrics.counter("claims.outbox.failed", "effect", message.effect()).increment();
 46	                log.warn("mock_effect_delivery_failed eventId={} effect={} exceptionType={}",
 47	                        message.id(), message.effect(), failure.getClass().getSimpleName());
 48	            }
 49	        }
 50	    }
 51	}

   284	    private ClaimFacts mergeFacts(Claim current, ClaimFacts patch, Actor actor) {
   285	        if (patch.values().isEmpty()) throw invalid("At least one fact must be supplied");
   286	        Map<String, Object> merged = new LinkedHashMap<>(current.facts().values());
   287	        for (var entry : patch.values().entrySet()) {
   288	            String key = entry.getKey();
   289	            if (!TOP_LEVEL_FACTS.contains(key)) throw forbidden("Claim fact is not writable: " + key);
   290	            if (key.equals("documents")) merged.put(key, mergeDocuments(current, merged.get(key), entry.getValue(), actor));
   291	            else if (key.equals("assessorId")) {
   292	                if (!actor.hasRole("team_lead") || !Set.of("SUBMITTED", "DOCUMENTS_VERIFIED").contains(current.state()))
   293	                    throw forbidden("Only a team lead may assign an assessor before assessment starts");
   294	                if (!(entry.getValue() instanceof String s) || s.isBlank()) throw invalid("assessorId must be a nonblank string");
   295	                merged.put(key, entry.getValue());
   296	            } else {
   297	                if (!actor.hasRole("assessor") || !current.state().equals("UNDER_ASSESSMENT")
   298	                        || !Objects.equals(actor.id(), current.facts().values().get("assessorId")))
   299	                    throw forbidden("Only the assigned assessor may submit an assessment report");
   300	                if (!(entry.getValue() instanceof Map<?, ?> report) || !(report.get("complete") instanceof Boolean))
   301	                    throw invalid("assessmentReport must contain a boolean complete field");
   302	                merged.put(key, entry.getValue());
   303	            }
   304	        }
   305	        return new ClaimFacts(merged);
   306	    }
