   308	    private Map<String, Object> mergeDocuments(Claim claim, Object existingRaw, Object patchRaw, Actor actor) {
   309	        if (!(patchRaw instanceof Map<?, ?> patch) || patch.isEmpty()) throw invalid("documents must be a nonempty object");
   310	        Map<String, Object> existing = existingRaw instanceof Map<?, ?> map ? mutableMap(map) : new LinkedHashMap<>();
   311	        Map<String, Object> result = new LinkedHashMap<>(existing);
   312	        for (var entry : patch.entrySet()) {
   313	            if (!(entry.getKey() instanceof String id) || !DOCUMENT_ID.matcher(id).matches()) throw invalid("Document ID is invalid");
   314	            if (!(entry.getValue() instanceof Map<?, ?> rawFields) || rawFields.isEmpty()) throw invalid("Document fields must be a nonempty object");
   315	            boolean member = actor.hasRole("member");
   316	            boolean clerk = actor.hasRole("document_clerk");
   317	            if (member && !claim.memberId().equals(actor.id())) throw forbidden("Member does not own this claim");
   318	            if (member && !claim.state().equals("PENDING_INFO")) throw forbidden("Members may add information only while a claim is pending information");
   319	            if (clerk && !Set.of("SUBMITTED", "PENDING_INFO").contains(claim.state())) throw forbidden("Documents cannot be updated in this claim state");
   320	            if (!member && !clerk) throw forbidden("Only the claim member or document clerk may update documents");
   321	            Object oldRaw = existing.get(id);
   322	            boolean isNew = oldRaw == null;
   323	            if (member && isNew) throw forbidden("Members cannot add document roster entries");
   324	            if (isNew && !clerk) throw forbidden("Only a document clerk may add document roster entries");
   325	            Map<String, Object> fields = oldRaw instanceof Map<?, ?> map ? mutableMap(map) : new LinkedHashMap<>();
   326	            for (var field : rawFields.entrySet()) {
   327	                if (!(field.getKey() instanceof String name) || !(field.getValue() instanceof Boolean)) throw invalid("Document fields must be booleans");
   328	                if (member && !name.equals("present")) throw forbidden("Members may only update document presence");
   329	                if (clerk && !Set.of("required", "present", "valid").contains(name)) throw invalid("Unknown document field: " + name);
   330	                if (name.equals("required") && !isNew && !claim.state().equals("SUBMITTED")) throw forbidden("Existing document required status is immutable after submission");
   331	                fields.put(name, field.getValue());
   332	            }
   333	            if (!(fields.get("required") instanceof Boolean) || !(fields.get("present") instanceof Boolean)
   334	                    || !(fields.get("valid") instanceof Boolean)) throw invalid("Document entry must contain required, present and valid boolean fields");
   335	            result.put(id, Map.copyOf(fields));
   336	        }
   337	        return Map.copyOf(result);
   338	    }
