   340	    private static Map<String, Object> mutableMap(Map<?, ?> source) {
   341	        Map<String, Object> result = new LinkedHashMap<>();
   342	        source.forEach((k, v) -> { if (k instanceof String key) result.put(key, v); });
   343	        return result;
   344	    }
