17	@Configuration
18	@EnableWebSecurity
19	public class SecurityConfiguration {
20	    @Bean
21	    PasswordEncoder passwordEncoder() { return PasswordEncoderFactories.createDelegatingPasswordEncoder(); }
22	
23	    @Bean
24	    InMemoryUserDetailsManager users(PasswordEncoder encoder,
25	            @Value("${claims.security.demo-password:}") String humanPassword,
26	            @Value("${claims.security.system-password:}") String systemPassword) {
27	        requireConfiguredSecret(humanPassword, "CLAIMS_DEMO_PASSWORD");
28	        requireConfiguredSecret(systemPassword, "CLAIMS_SYSTEM_PASSWORD");
29	        return new InMemoryUserDetailsManager(
30	                User.withUsername("clerk").password(encoder.encode(humanPassword)).roles("DOCUMENT_CLERK").build(),
31	                User.withUsername("lead").password(encoder.encode(humanPassword)).roles("TEAM_LEAD").build(),
32	                User.withUsername("assessor").password(encoder.encode(humanPassword)).roles("ASSESSOR").build(),
33	                User.withUsername("finance").password(encoder.encode(humanPassword)).roles("FINANCE").build(),
34	                User.withUsername("member-demo").password(encoder.encode(humanPassword)).roles("MEMBER").build(),
35	                User.withUsername("system").password(encoder.encode(systemPassword)).roles("SYSTEM").build());
36	    }
37	
38	    @Bean
39	    SecurityFilterChain security(HttpSecurity http, ObjectMapper json) throws Exception {
40	        return http
41	                .authorizeHttpRequests(auth -> auth
