43	                        .anyRequest().authenticated())
44	                .httpBasic(Customizer.withDefaults())
45	                .csrf(Customizer.withDefaults())
46	                .exceptionHandling(errors -> errors.authenticationEntryPoint(new JsonSecurityHandlers(json))
