    14	            Map.entry("assessment_report_complete", c -> reportComplete(c.claim().facts().values().get("assessmentReport"))),
    15	            Map.entry("amount_within_policy_limit", c -> amountWithin(
    16	                    c.claim().facts().values().get("requestedAmount"), c.claim().policyLimit())),
    17	            Map.entry("rejection_reason_present", c -> nonblank(c.command().reason())),
    18	            Map.entry("information_description_present", c -> nonblank(c.command().reason())),
    19	            Map.entry("new_information_received", this::newInformationReceived),
    20	            Map.entry("payment_request_exists", c -> c.evidence().paymentRequestExists()),
    21	            Map.entry("payment_confirmed", this::paymentConfirmed),
    22	            Map.entry("appeal_period_expired_or_member_acknowledged", this::appealResolved));
    23	
    24	    public Set<String> strategyIds() {
    25	        return strategies.keySet();
    26	    }
    27	
    28	    public boolean passes(String id, WorkflowEvaluationContext c) {
    29	        Predicate<WorkflowEvaluationContext> strategy = strategies.get(id);
    30	        return strategy != null && strategy.test(c);
    31	    }
    32	
    33	    private boolean allRequiredDocumentsPresent(WorkflowEvaluationContext context) {
    34	        return documentsValid(context.claim().facts().values());
    35	    }
    36	
    37	    private boolean newInformationReceived(WorkflowEvaluationContext context) {
    38	        WorkflowEvidence evidence = context.evidence();
    39	        return evidence.lastInformationRequestedAt() != null && evidence.lastInformationReceivedAt() != null
    40	                && evidence.lastInformationReceivedAt().isAfter(evidence.lastInformationRequestedAt());
    41	    }
    42	
    43	    private boolean paymentConfirmed(WorkflowEvaluationContext context) {
    44	        WorkflowEvidence evidence = context.evidence();
    45	        return evidence.paymentRequestExists() && evidence.paymentConfirmedAt() != null
    46	                && nonblank(evidence.paymentReference());
    47	    }
    48	
    49	    private boolean appealResolved(WorkflowEvaluationContext context) {
    50	        WorkflowEvidence evidence = context.evidence();
    51	        return evidence.rejectedAt() != null &&
    52	                ((evidence.memberAcknowledgedRejectionAt() != null
    53	                        && !evidence.memberAcknowledgedRejectionAt().isBefore(evidence.rejectedAt()))
    54	                        || !context.now().isBefore(evidence.rejectedAt().plus(context.appealPeriod())));
    55	    }
