 30	
 31	    @Override
 32	    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
 33	            throws ServletException, IOException {
 34	        String type = request.getContentType();
 35	        if (!request.getRequestURI().startsWith("/api/") || type == null
 36	                || !type.toLowerCase(java.util.Locale.ROOT).startsWith(MediaType.APPLICATION_JSON_VALUE)) {
 37	            chain.doFilter(request, response); return;
 38	        }
 39	        byte[] body = request.getInputStream().readNBytes(MAX_BYTES + 1);
 40	        if (body.length > MAX_BYTES) {
 41	            response.setStatus(413); response.setContentType(MediaType.APPLICATION_JSON_VALUE);
 42	            json.writeValue(response.getOutputStream(), new ApiError("REQUEST_TOO_LARGE", "JSON request body exceeds 65536 bytes",
 43	                    List.of(), CorrelationIdFilter.currentId(request)));
 44	            return;
 45	        }
 46	        chain.doFilter(new CachedBodyRequest(request, body), response);
 47	    }
 48	
 49	    private static final class CachedBodyRequest extends HttpServletRequestWrapper {
 50	        private final byte[] body;
 51	        CachedBodyRequest(HttpServletRequest request, byte[] body) { super(request); this.body = body; }
 52	        @Override public ServletInputStream getInputStream() {
 53	            ByteArrayInputStream input = new ByteArrayInputStream(body);
 54	            return new ServletInputStream() {
 55	                @Override public int read() { return input.read(); }
 56	                @Override public boolean isFinished() { return input.available() == 0; }
 57	                @Override public boolean isReady() { return true; }
 58	                @Override public void setReadListener(ReadListener listener) { throw new UnsupportedOperationException("Async request bodies are not supported"); }
 59	            };
 60	        }
 61	        @Override public BufferedReader getReader() { return new BufferedReader(new InputStreamReader(getInputStream(), StandardCharsets.UTF_8)); }
 62	        @Override public int getContentLength() { return body.length; }
 63	        @Override public long getContentLengthLong() { return body.length; }
 64	    }
 65	}
