 18	@RestControllerAdvice
 19	public class GlobalExceptionHandler {
 20	    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);
 21	
 22	    @ExceptionHandler(BusinessException.class)
 23	    ResponseEntity<ApiError> business(BusinessException error, HttpServletRequest request) {
 24	        return response(error.status(), error.code(), error.getMessage(), List.of(), request);
 25	    }
 26	
 27	    @ExceptionHandler(MethodArgumentNotValidException.class)
 28	    ResponseEntity<ApiError> invalid(MethodArgumentNotValidException error, HttpServletRequest request) {
 29	        List<String> details = error.getBindingResult().getFieldErrors().stream()
 30	                .map(field -> field.getField() + ": " + field.getDefaultMessage()).toList();
 31	        return response(400, "VALIDATION_ERROR", "Request validation failed", details, request);
 32	    }
 33	
 34	    @ExceptionHandler({HttpMessageNotReadableException.class, MissingRequestHeaderException.class,
 35	            MethodArgumentTypeMismatchException.class, IllegalArgumentException.class})
 36	    ResponseEntity<ApiError> malformed(Exception error, HttpServletRequest request) {
 37	        return response(400, "INVALID_REQUEST", "Request is malformed or contains an invalid value", List.of(), request);
 38	    }
 39	
 40	    @ExceptionHandler(Exception.class)
 41	    ResponseEntity<ApiError> unexpected(Exception error, HttpServletRequest request) {
 42	        log.error("request_failed correlationId={} exceptionType={}", CorrelationIdFilter.currentId(request), error.getClass().getSimpleName());
 43	        return response(500, "INTERNAL_ERROR", "The request could not be completed", List.of(), request);
 44	    }
 45	
 46	    private static ResponseEntity<ApiError> response(int status, String code, String message,
 47	            List<String> details, HttpServletRequest request) {
 48	        return ResponseEntity.status(status).body(new ApiError(code, message, details, CorrelationIdFilter.currentId(request)));
 49	    }
