  9	final class PersistenceMapping {
 10	    private static final TypeReference<Map<String,Object>> MAP = new TypeReference<>() {};
 11	    private PersistenceMapping() {}
 12	    static String json(ObjectMapper mapper, Object value) {
 13	        try { return mapper.writeValueAsString(value); }
 14	        catch (JsonProcessingException e) { throw new IllegalArgumentException("Could not encode persistence JSON", e); }
 15	    }
 16	    static Map<String,Object> map(ObjectMapper mapper, String value) {
 17	        try { return mapper.readValue(value, MAP); }
 18	        catch (JsonProcessingException e) { throw new IllegalStateException("Could not decode persisted JSON", e); }
 19	    }
 20	    static ClaimAggregate aggregate(ObjectMapper mapper, ClaimRow r) {
 21	        Claim c = new Claim(r.id, r.memberId, r.state, r.policyLimit, r.currency, r.version,
 22	                new ClaimFacts(map(mapper, r.factsJson)), r.createdAt, r.updatedAt);
 23	        return new ClaimAggregate(c, new ClaimWorkflowData(r.informationRequests, r.lastInformationRequestedAt,
 24	                r.lastInformationReceivedAt, r.assessmentStartedAt, r.rejectedAt, r.memberAcknowledgedRejectionAt));
 25	    }
 26	    static ClaimRow row(ObjectMapper mapper, ClaimAggregate a) {
 27	        Claim c = a.claim(); ClaimWorkflowData w = a.workflow(); ClaimRow r = new ClaimRow();
 28	        r.id=c.id(); r.memberId=c.memberId(); r.state=c.state(); r.policyLimit=c.policyLimit(); r.currency=c.currency();
 29	        r.version=c.version(); r.factsJson=json(mapper,c.facts().values()); r.informationRequests=w.informationRequests();
 30	        r.lastInformationRequestedAt=w.lastInformationRequestedAt(); r.lastInformationReceivedAt=w.lastInformationReceivedAt();
 31	        r.assessmentStartedAt=w.assessmentStartedAt(); r.rejectedAt=w.rejectedAt();
 32	        r.memberAcknowledgedRejectionAt=w.memberAcknowledgedRejectionAt(); r.createdAt=c.createdAt(); r.updatedAt=c.updatedAt(); return r;
 33	    }
 34	}
