10	public final class WorkflowConfigLoader {
11	    private static final Set<String> SUPPORTED_ROLES = Set.of("document_clerk", "team_lead", "assessor", "finance", "system");
12	    private final ObjectMapper mapper = new ObjectMapper(new YAMLFactory())
13	            .enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION);
14	    private final GuardEvaluator guardRegistry;
15	    private final EffectRegistry effectRegistry;
16	
17	    public WorkflowConfigLoader() {
18	        this(new GuardEvaluator(), new EffectRegistry());
19	    }
20	
21	    public WorkflowConfigLoader(GuardEvaluator guardRegistry, EffectRegistry effectRegistry) {
22	        this.guardRegistry = guardRegistry;
23	        this.effectRegistry = effectRegistry;
24	    }
25	    public WorkflowDefinition load(InputStream input) {
26	        try {
27	            Map<?,?> root = map(mapper.readValue(input, Map.class), "root");
28	            Map<?,?> w = map(root.get("workflow"), "workflow");
29	            Set<String> states = uniqueStrings(w.get("states"), "states");
30	            String initialState = text(w.get("initial-state"));
31	            if (!states.contains(initialState)) throw bad("Initial state is not declared");
32	            Map<String,String> guards = new LinkedHashMap<>();
33	            map(w.get("guard-catalog"),"guard-catalog").forEach((k,v)-> {
34	                String id = text(k);
35	                if (!guardRegistry.strategyIds().contains(id)) throw bad("Unknown guard strategy: " + id);
36	                guards.put(id, text(map(v,"guard").get("failure-message")));
37	            });
38	            Map<String,String> effects = new LinkedHashMap<>();
39	            map(w.get("effect-catalog"),"effect-catalog").forEach((k,v)-> {
40	                String id = text(k);
41	                if (!effectRegistry.supports(id)) throw bad("Unknown effect strategy: " + id);
42	                effects.put(id, text(v));
43	            });
44	            List<WorkflowDefinition.Transition> ts=new ArrayList<>(); Set<String> ids=new HashSet<>(); Set<String> edges=new HashSet<>();
45	            for(Object o:(List<?>)w.get("transitions")) { Map<?,?> t=map(o,"transition"); String id=text(t.get("id")), from=text(t.get("from")), to=text(t.get("to"));
46	                if(!ids.add(id)||!edges.add(from+"\u0000"+to)) throw bad("Duplicate transition id or edge"); if(!states.contains(from)||!states.contains(to)) throw bad("Dangling transition state");
47	                List<String> gs=List.copyOf(uniqueStrings(t.get("guards"),"guards")), es=List.copyOf(uniqueStrings(t.get("effects"),"effects")); if(!guards.keySet().containsAll(gs)||!effects.keySet().containsAll(es)) throw bad("Transition references unknown guard or effect");
48	                Set<String> roles = new LinkedHashSet<>(uniqueStrings(t.get("authorized-roles"), "authorized-roles"));
49	                if (roles.isEmpty() || !SUPPORTED_ROLES.containsAll(roles)) throw bad("Transition has missing or unknown roles");
50	                ts.add(new WorkflowDefinition.Transition(id,from,to,roles,gs,es)); }
51	            Map<?,?> cp=map(w.get("cycle-policy"),"cycle-policy");
52	            String cycleTransition = text(cp.get("transition-id"));
53	            String counter = text(cp.get("counter"));
54	            int max = positiveInteger(cp.get("maximum"), "cycle-policy.maximum");
55	            String cycleMessage = text(cp.get("error-message"));
56	            if (ts.stream().noneMatch(t -> t.id().equals(cycleTransition))) throw bad("Cycle policy transition is unknown");
57	            if (!"informationRequests".equals(counter)) throw bad("Unknown cycle counter: " + counter);
58	            if (w.containsKey("information-cycle-limit") && positiveInteger(w.get("information-cycle-limit"), "information-cycle-limit") != max)
59	                throw bad("Information cycle limit must match cycle policy maximum");
60	            return new WorkflowDefinition(text(w.get("version")),initialState,states,ts,guards,effects,
61	                    new WorkflowDefinition.CyclePolicy(cycleTransition,counter,max,cycleMessage));
62	        } catch(IOException|ClassCastException|NullPointerException ex) { throw new IllegalArgumentException("Invalid workflow configuration",ex); }
63	    }
64	    private static Map<?,?> map(Object x,String label){if(!(x instanceof Map<?,?> m))throw bad("Missing/invalid "+label);return m;}
65	    private static List<String> strings(Object x,String label){if(!(x instanceof List<?> l))throw bad("Missing/invalid "+label);return l.stream().map(WorkflowConfigLoader::text).toList();}
66	    private static Set<String> uniqueStrings(Object x, String label) {
67	        List<String> values = strings(x, label);
68	        Set<String> unique = new LinkedHashSet<>(values);
69	        if (unique.size() != values.size()) throw bad("Duplicate value in " + label);
70	        return unique;
71	    }
72	    private static int positiveInteger(Object value, String label) {
73	        if (!(value instanceof Number number)) throw bad("Missing/invalid " + label);
74	        long n = number.longValue();
75	        if (n <= 0 || n > Integer.MAX_VALUE || number.doubleValue() != n) throw bad("Invalid " + label);
76	        return (int) n;
77	    }
78	    private static String text(Object x){if(!(x instanceof String s)||s.isBlank())throw bad("Expected nonblank string");return s;}
79	    private static IllegalArgumentException bad(String m){return new IllegalArgumentException(m);}
80	}

