 3	import java.util.LinkedHashMap;
 4	import java.util.Map;
 5	import java.util.Set;
 6	import java.util.function.Function;
 7	
 8	/** Registry of pure effect planners; external work is dispatched only after commit. */
 9	public final class EffectRegistry {
10	    private final Map<String, Function<WorkflowEvaluationContext, EffectIntent>> strategies;
11	
12	    public EffectRegistry() {
13	        Map<String, Function<WorkflowEvaluationContext, EffectIntent>> registered = new LinkedHashMap<>();
14	        registered.put("notify_assessor_team", c -> plan("notify_assessor_team", "claimId", c.claim().id().toString()));
15	        registered.put("record_assessment_start", c -> plan("record_assessment_start", "occurredAt", c.now().toString()));
16	        registered.put("notify_member_approval", c -> plan("notify_member_approval", "claimId", c.claim().id().toString()));
17	        registered.put("create_payment_request", c -> new EffectIntent("create_payment_request", Map.of(
18	                "claimId", c.claim().id().toString(), "currency", c.claim().currency(),
19	                "amount", c.claim().facts().values().get("requestedAmount"))));
20	        registered.put("notify_member_rejection", c -> plan("notify_member_rejection", "reason", c.command().reason()));
21	        registered.put("notify_information_request", c -> plan("notify_information_request", "description", c.command().reason()));
22	        registered.put("reset_assessment_timer", c -> plan("reset_assessment_timer", "occurredAt", c.now().toString()));
23	        registered.put("trigger_payment_system", c -> plan("trigger_payment_system", "claimId", c.claim().id().toString()));
24	        registered.put("notify_member_payment_reference", c -> plan("notify_member_payment_reference", "reference", c.evidence().paymentReference()));
25	        registered.put("archive_claim", c -> plan("archive_claim", "claimId", c.claim().id().toString()));
26	        strategies = Map.copyOf(registered);
27	    }
28	
29	    public Set<String> strategyIds() {
30	        return strategies.keySet();
31	    }
32	
33	    public boolean supports(String id) {
34	        return strategies.containsKey(id);
35	    }
36	
37	    public EffectIntent resolve(String id, WorkflowEvaluationContext context) {
38	        Function<WorkflowEvaluationContext, EffectIntent> strategy = strategies.get(id);
39	        if (strategy == null) throw new IllegalArgumentException("Unknown effect strategy: " + id);
40	        return strategy.apply(context);
41	    }
42	
43	    private static EffectIntent plan(String id, String key, Object value) {
44	        return new EffectIntent(id, Map.of(key, value));
45	    }
46	}
