    22	public class CorrelationIdFilter extends OncePerRequestFilter {
    23	    public static final String HEADER = "X-Correlation-ID";
    24	    public static final String ATTRIBUTE = CorrelationIdFilter.class.getName() + ".id";
    25	    private static final Pattern SAFE = Pattern.compile("[A-Za-z0-9._:-]{1,128}");
    26	    private static final Logger log = LoggerFactory.getLogger(CorrelationIdFilter.class);
    27	    private final ObservationRegistry observations;
    28	
    29	    public CorrelationIdFilter(ObservationRegistry observations) { this.observations = observations; }
    30	
    31	    @Override
    32	    protected void doFilterInternal(HttpServletRequest request, HttpServletResponse response, FilterChain chain)
    33	            throws ServletException, IOException {
    34	        String supplied = request.getHeader(HEADER);
    35	        String correlationId = supplied != null && SAFE.matcher(supplied).matches() ? supplied : UUID.randomUUID().toString();
    36	        request.setAttribute(ATTRIBUTE, correlationId);
    37	        response.setHeader(HEADER, correlationId);
    38	        MDC.put("correlationId", correlationId);
    39	        long started = System.nanoTime();
    40	        Observation observation = Observation.createNotStarted("claims.http.filter", observations)
    41	                .lowCardinalityKeyValue("method", request.getMethod());
    42	        observation.start();
    43	        try (Observation.Scope ignored = observation.openScope()) {
    44	            try {
    45	                chain.doFilter(request, response);
    46	            } catch (ServletException | IOException | RuntimeException failure) {
    47	                observation.error(failure);
    48	                throw failure;
    49	            } finally {
    50	                long durationMs = (System.nanoTime() - started) / 1_000_000;
    51	                log.info("http_request method={} path={} status={} durationMs={} correlationId={} traceId={} spanId={}",
    52	                        request.getMethod(), request.getRequestURI(), response.getStatus(), durationMs, correlationId,
    53	                        MDC.get("traceId"), MDC.get("spanId"));
    54	            }
    55	        } finally {
    56	            observation.stop();
    57	            MDC.remove("correlationId");
    58	        }
    59	    }
    60	
    61	    public static String currentId(HttpServletRequest request) {
    62	        Object value = request.getAttribute(ATTRIBUTE);
    63	        return value instanceof String id ? id : UUID.randomUUID().toString();
    64	    }
